from pydantic.dataclasses import dataclass
from pydantic import BaseModel

@dataclass
class PatientMedicalChart:
    ssn: str
    diagnostic_codes: list[str]
    psychiatric_notes: str

class ClaimDetailResponse(BaseModel):
    claim_id: str
    billing_amount: float
    chart: PatientMedicalChart

    class Config:
        from_attributes = True

@router.get("/claims/{claim_id}", response_model=ClaimDetailResponse)
async def get_claim_details(
    claim_id: str,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    claim = db.query(InsuranceClaim).filter(InsuranceClaim.id == claim_id).first()
    if not claim:
        raise HTTPException(status_code=404, detail="Insurance claim not found")
    if claim.patient_id != current_user.id and not current_user.is_claims_adjuster:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized access to patient medical claim")
    return claim
